  ('1059913330639352725', 'The Ramparts of Ice', 2026, 'Animation, Drama, Comedy', null, null, 'Anna Nagase, Shoya Chiba, Fuka Izumi, Satoshi Inomata, Chiaki Kobayashi, Sakura Shinfuku, Akari Kito, Kakeru Hatano', 'TV-PG', 'Weighed down by memories she can''t shake, high schooler Koyuki Hikawa keeps everyone at arm''s length — until three schoolmates draw her out of her shell.', 'Weighed down by memories she can''t shake, high schooler Koyuki Hikawa keeps everyone at arm''s length — until three schoolmates draw her out of her shell.', 'https://image.tmdb.org/t/p/w500/rke9UC2QrogvxiQD9TGpbvqDosi.jpg', 1, 'tmdb:tv:283428'),
  ('964091858948906660', 'The Ranch', 2016, 'Comedy, Family, Western', 'Jim Patterson, Don Reo', null, 'Ashton Kutcher, Elisha Cuthbert, Sam Elliott, Debra Winger, Grady Lee Richmond, Kelli Goss', 'TV-MA', 'Being a pro athlete didn''t pan out for Colt. Now he''s helping his dad and brother keep the ranch afloat, and figuring out how he fits into the family.', 'Being a pro athlete didn''t pan out for Colt. Now he''s helping his dad and brother keep the ranch afloat, and figuring out how he fits into the family.', 'https://image.tmdb.org/t/p/w500/lrbHBAxF9Ir83rxgeBrfmEJriLt.jpg', 4, 'tmdb:tv:65493'),
